package com.anonymousdust.overlay;
import android.app.*; import android.content.*; import android.graphics.Color; import android.graphics.drawable.GradientDrawable; import android.os.*; import android.provider.Settings; import android.view.*; import android.widget.*;
public class LoveOverlayService extends Service { WindowManager wm; View v; TextView text; public IBinder onBind(Intent i){return null;} public int onStartCommand(Intent i,int f,int s){String m=i==null?null:i.getStringExtra("message"); show(m==null||m.trim().isEmpty()?"AKU SAYANG KAMU\nMIA SAYANG":m); return START_NOT_STICKY;} void show(String message){if(v!=null){text.setText("♥  ♥  ♥\n"+message+"\n♥  Selalu di hatiku  ♥");return;} wm=(WindowManager)getSystemService(WINDOW_SERVICE); LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setGravity(Gravity.CENTER); box.setPadding(35,22,35,22); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xffff9fbe,0xffffd6e7}); bg.setCornerRadius(35); box.setBackground(bg); text=new TextView(this); text.setText("♥  ♥  ♥\n"+message+"\n♥  Selalu di hatiku  ♥"); text.setGravity(Gravity.CENTER); text.setTextColor(0xffb51f55); text.setTextSize(30); text.setTypeface(null,1); box.addView(text); box.setOnClickListener(q->stopSelf()); v=box; int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE; WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,-3); p.gravity=Gravity.CENTER; wm.addView(v,p); } public void onDestroy(){if(v!=null){wm.removeView(v);v=null;}super.onDestroy();}}
